package com.bemo.hr.product.analytics;import jakarta.persistence.*;import lombok.Getter;import org.hibernate.annotations.TenantId;import java.time.*;import java.util.UUID;@Entity@Table(name="product_event_daily_aggregates")@Getter public class ProductEventDailyAggregate{@Id private String id;@TenantId@Column(name="app_id",nullable=false)private String appId;@Column(name="event_date",nullable=false)private LocalDate eventDate;@Column(name="event_name",nullable=false)private String eventName;@Column(name="feature_key",nullable=false)private String featureKey;@Column(name="event_count",nullable=false)private long eventCount;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;protected ProductEventDailyAggregate(){}public ProductEventDailyAggregate(LocalDate date,String name,String feature){id=UUID.randomUUID().toString();eventDate=date;eventName=name;featureKey=feature;eventCount=1;updatedAt=Instant.now();}public void increment(){eventCount++;updatedAt=Instant.now();}}
